import axios from "axios";

const API_BASE = "http://localhost:3001";

axios.defaults.withCredentials = true;

// LOGIN
export async function login(username, password) {
  const res = await axios.post(`${API_BASE}/api/login`, { username, password });
  return res.data;
}

// REQUESTS
export async function fetchRequests() {
  const res = await axios.get(`${API_BASE}/api/requests`);
  return res.data;
}

export async function assignRequest(id, assigned_to) {
  return axios.post(`${API_BASE}/api/requests/${id}/assign`, {
    assigned_to,
  });
}

export async function updateStatus(id, status) {
  return axios.post(`${API_BASE}/api/requests/${id}/status`, { status });
}

// DASHBOARD STATS
export async function fetchStats() {
  const res = await axios.get(`${API_BASE}/api/stats`);
  return res.data;
}

export async function fetchRecentRequests() {
  const res = await axios.get(`${API_BASE}/api/requests/recent`);
  return res.data;
}
